import{_ as t,o,c as a,ah as r}from"./chunks/framework.CRsDMGp2.js";const p=JSON.parse('{"title":"Guide — External contributor","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/contributeur-externe.md","filePath":"src/en/guide/contributeur-externe.md"}'),n={name:"en/guide/contributeur-externe.md"};function i(s,e,l,c,h,d){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="guide-—-external-contributor" tabindex="-1">Guide — External contributor <a class="header-anchor" href="#guide-—-external-contributor" aria-label="Permalink to &quot;Guide — External contributor&quot;">​</a></h1><p>Send your pole&#39;s requests to Naia.</p><h2 id="welcome-to-naia" tabindex="-1">Welcome to Naia <a class="header-anchor" href="#welcome-to-naia" aria-label="Permalink to &quot;Welcome to Naia&quot;">​</a></h2><p>You belong to one of edPage group&#39;s poles — Commercial, Support, HR or Billing — and your account lets you send your requests straight to Naia, instead of by e-mail or phone.</p><p>Your access is deliberately narrow: you only see <strong>My space</strong>, which holds your pole&#39;s form and the list of your submissions. You don&#39;t have access to projects, documents or messaging. Searches (client, project, collaborator) only show a reference and a name.</p><h2 id="getting-your-account" tabindex="-1">Getting your account <a class="header-anchor" href="#getting-your-account" aria-label="Permalink to &quot;Getting your account&quot;">​</a></h2><p>Your account is created by Naia&#39;s administrator, who gives you your credentials. On your first sign-in, change your password from <strong>Settings &gt; Security</strong> (the gear icon at the top of the screen). If you leave the pole, the administrator revokes your access.</p><h2 id="following-your-submissions" tabindex="-1">Following your submissions <a class="header-anchor" href="#following-your-submissions" aria-label="Permalink to &quot;Following your submissions&quot;">​</a></h2><p>The <strong>My submissions</strong> list, visible to you only, shows each submission with its status:</p><ul><li><strong>Sent</strong>: Naia has received your submission; it&#39;s waiting to be handled;</li><li><strong>Processed</strong>: its effect exists in Naia — the project is created, the task is added, the collaborator is assigned, or the payment status has been taken into account.</li></ul><p>There&#39;s nothing else for you to do: a submission switches to &quot;Processed&quot; on its own.</p><h2 id="commercial-pole" tabindex="-1">Commercial pole <a class="header-anchor" href="#commercial-pole" aria-label="Permalink to &quot;Commercial pole&quot;">​</a></h2><ul><li><strong>New project</strong>: for a client who has just signed, search for them or type their name if they&#39;re new, pick the project type, then <strong>Create the project</strong>. This is a request: an administrator validates it and appoints the project manager. The project then gets its reference (e.g. <code>NAIA-0142</code>).</li><li><strong>Report a development need</strong>: same form as the Support pole (below). The task created carries the <strong>Commercial</strong> badge.</li></ul><h2 id="support-pole" tabindex="-1">Support pole <a class="header-anchor" href="#support-pole" aria-label="Permalink to &quot;Support pole&quot;">​</a></h2><p><strong>Development need</strong>: when a ticket reveals a need for the development team:</p><ol><li>enter the ticket reference if you have one (e.g. <code>TCK-4821</code>) — it&#39;s optional;</li><li>pick the project concerned, or <strong>Unknown project</strong> if you don&#39;t know which project it is;</li><li>describe the need, then <strong>Send to Naia</strong>.</li></ol><p>On a known project, the need immediately becomes a task on the project, with the <strong>Support</strong> badge, and the project manager is notified. On an unknown project, an administrator picks the right project before creating the task.</p><h2 id="hr-pole" tabindex="-1">HR pole <a class="header-anchor" href="#hr-pole" aria-label="Permalink to &quot;HR pole&quot;">​</a></h2><p>The <strong>Pending reinforcement needs</strong> list gathers project managers&#39; reinforcement requests, with the required profile. For each one, pick the collaborator chosen among existing accounts, then <strong>Confirm the assignment</strong>: they automatically join the project team, and the project manager is notified.</p><p>A confirmed line disappears for every HR account: two people in the pole can&#39;t handle the same need. If the person chosen doesn&#39;t have a Naia account yet (an external expert, for instance), ask the administrator to create it first.</p><p>You&#39;re notified, in the app and by e-mail, of every new reinforcement need.</p><h2 id="billing-pole" tabindex="-1">Billing pole <a class="header-anchor" href="#billing-pole" aria-label="Permalink to &quot;Billing pole&quot;">​</a></h2><p>The <strong>Signalled billable milestones</strong> list shows each billable milestone validated on a project, with the amount Naia signalled. For each one, set the <strong>payment status</strong>, then <strong>Update the status</strong>:</p><ul><li><strong>Up to date</strong>: the payment is settled; the milestone leaves your list;</li><li><strong>Overdue</strong>: Direction and the administrator are alerted and decide whether to block the project. The milestone stays in your list: once the payment is settled, set it back to <strong>Up to date</strong> so the project can be unblocked.</li></ul><p>You&#39;re notified, in the app and by e-mail, of every new billable milestone. No accounting data is stored in Naia: you only record a status there.</p>',25)])])}const g=t(n,[["render",i]]);export{p as __pageData,g as default};
